#!/usr/bin/env python3
"""Generate finite Boolean and dyadic checks for the compact stabilizer."""

import argparse
from itertools import product
from pathlib import Path

HERE = Path(__file__).resolve().parent
NUM = "₀₁₂₃₄₅₆"


def header(name, description):
    return f"""------------------------------------------------------------------------
-- Presentations of groups
--
-- {description}
-- Generated by ThreeQubit/build_compact.py.
------------------------------------------------------------------------

{{-# OPTIONS --without-K --safe #-}}

module Examples.Groups.CCX+HH.ThreeQubit.Compact.{name} where

"""


def action():
    s = header("Action", "The 49 conjugation rules act correctly on all 128 sign states.")
    s += """open import Data.Bool.Base using (true ; false)
open import Data.Fin.Base using (Fin)
open import Data.Vec.Base using (_∷_ ; [])
open import Relation.Binary.PropositionalEquality using (_≡_ ; refl)
open import Notations
open import Examples.Groups.CCX+HH.ThreeQubit.Compact.Diagonal

checked : ∀ i s → transformed i s ≡ permuted i s
"""
    for i in range(7):
        for bits in product((False, True), repeat=7):
            pattern = " ∷ ".join("true" if b else "false" for b in bits) + " ∷ []"
            s += f"checked {NUM[i]} ({pattern}) = refl\n"
    return s


def source():
    s = header("SourceChecks", "Short exact dyadic identities for the compact auxiliary rules.")
    s += """open import Relation.Binary.PropositionalEquality using (_≡_ ; refl)
open import Notations
open import Word.Base using (_•_ ; _ʷ)
open import Examples.Groups.CCX+HH.ThreeQubit.Compact.Syntactics
open import Examples.Groups.CCX+HH.ThreeQubit.StabilizerGenerators using (b)
open import Examples.Groups.CCX+HH-TwoLevel.Ring using (_+ᴰ_ ; _*ᴰ_ ; -ᴰ_)
import Examples.Groups.CCX+HH-TwoLevel.Semantics as S
open S using (actV ; set₁ ; set₂)

opaque
  unfolding actV set₁ set₂ _+ᴰ_ _*ᴰ_ -ᴰ_

  square : ∀ i → S.⟦ (b ʷ) (P i • P i) ⟧ᵐ ≡ S.𝕀
"""
    for i in range(7):
        s += f"  square {NUM[i]} = refl\n"
    s += "\n  commute : ∀ i j → S.⟦ (b ʷ) (P i • P j) ⟧ᵐ ≡ S.⟦ (b ʷ) (P j • P i) ⟧ᵐ\n"
    for i in range(7):
        for j in range(7):
            s += f"  commute {NUM[i]} {NUM[j]} = refl\n"
    s += "\n  crossing : ∀ i j → S.⟦ (b ʷ) (X i • P j) ⟧ᵐ ≡ S.⟦ (b ʷ) ((P ʷ) (conjugate i j) • X i) ⟧ᵐ\n"
    for i in range(7):
        for j in range(7):
            s += f"  crossing {NUM[i]} {NUM[j]} = refl\n"
    return s


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="compare without writing")
    args = parser.parse_args()
    for name, text in (("Action", action()), ("SourceChecks", source())):
        path = HERE / "Compact" / f"{name}.agda"
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != text:
                raise SystemExit(f"Generated file differs: {path}")
        else:
            path.parent.mkdir(exist_ok=True)
            path.write_text(text, encoding="utf-8")
    print(("Verified" if args.check else "Generated") + " 896 Boolean actions and 105 dyadic identities.")


if __name__ == "__main__":
    main()
